export const PROJECT_NOTE =
  'Fanowska, proceduralna interpretacja Hogwartu inspirowana filmami i książkami. Układ łączy kilka wersji zamku; nie jest rekonstrukcją pomiarową 1:1. Profesorowie pochodzą z różnych lat historii szkoły. Dialogi, zadania i gesty różdżki przygotowano na potrzeby tej wycieczki.';

const lesson = (title, intro, question, choices, answer, success, gesture = 'up') => ({
  title,
  intro,
  question,
  choices,
  answer,
  success,
  gesture,
});

